class BookRepository {
  constructor() {
    this._books = new Map();
    this._nextId = 1;
  }

  add(title, author) {
    const id = this._nextId++;
    const book = { id, title, author };
    this._books.set(id, book);
    return book;
  }

  get(id) {
    return this._books.get(id) || null;
  }

  list() {
    return [...this._books.values()];
  }
}

module.exports = BookRepository;

