const http = require('http');
function request(app, method, path, body) {
  return new Promise((resolve, reject) => {
    const server = app.listen(0, () => {
      const port = server.address().port;
      const data = body === undefined ? null : JSON.stringify(body);
      const headers = data
        ? { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(data) }
        : {};
      const req = http.request(
        { host: '127.0.0.1', port, path, method, headers, timeout: 4000 },
        (res) => {
          let buf = '';
          res.on('data', (c) => (buf += c));
          res.on('end', () => {
            server.close();
            let json = null;
            try { json = JSON.parse(buf); } catch (e) { /* non-JSON */ }
            resolve({ status: res.statusCode, body: json, raw: buf });
          });
        }
      );
      req.on('timeout', () => { req.destroy(new Error('request timed out (handler never responded)')); });
      req.on('error', (e) => { server.close(); reject(e); });
      if (data) req.write(data);
      req.end();
    });
  });
}

const assert = require('assert');
const app = require('./src/app');

(async () => {
  let r = await request(app, 'POST', '/reviews', { bookId: 7, rating: 5, text: 'great' });
  assert(r.status === 201, `POST /reviews: ${r.status} ${r.raw}`);
  assert.deepStrictEqual(r.body, { id: 1, bookId: 7, rating: 5, text: 'great' });

  r = await request(app, 'POST', '/reviews', { bookId: 7, rating: 3, text: 'ok' });
  assert.strictEqual(r.body.id, 2, 'review ids must auto-increment');

  r = await request(app, 'POST', '/reviews', { bookId: 99, rating: 1, text: 'other book' });
  assert.strictEqual(r.body.id, 3);

  r = await request(app, 'GET', '/reviews?bookId=7');
  assert.strictEqual(r.status, 200);
  assert.deepStrictEqual(r.body.map((x) => x.text), ['great', 'ok'], 'reviews for book 7, in order');

  r = await request(app, 'GET', '/reviews?bookId=99');
  assert.strictEqual(r.body.length, 1);

  // books resource still works
  r = await request(app, 'POST', '/books', { title: 'T', author: 'A' });
  assert(r.status === 201, `books route broke: ${r.status}`);
  console.log('PASS');
})().catch((e) => { console.error(e); process.exit(1); });

