class ReviewRepository {
  constructor() {
    this._reviews = [];
    this._nextId = 1;
  }

  add(bookId, rating, text) {
    const review = { id: this._nextId++, bookId, rating, text };
    this._reviews.push(review);
    return review;
  }

  listForBook(bookId) {
    return this._reviews.filter((r) => r.bookId === bookId);
  }
}

module.exports = ReviewRepository;

